function Get-WingiShowMetadata {
        param(
            [string[]]$ArgsList,
            [switch]$StoreExact
        )

        if ($StoreExact) {
            $bare = Get-WingiBareTokens -ArgsList $ArgsList
            if (-not $bare.Count) { return $null }
            $tempFile = Join-Path $env:TEMP ('wingi-show-' + [System.Guid]::NewGuid().ToString('N') + '.txt')
            cmd /c "winget show --id $($bare[0]) --source msstore --exact --accept-source-agreements --disable-interactivity > `"$tempFile`" 2>&1" | Out-Null
            $rawLines = if (Test-Path $tempFile) { Get-Content $tempFile -ErrorAction SilentlyContinue } else { @() }
            Remove-Item $tempFile -Force -ErrorAction SilentlyContinue
        } else {
            $rawLines = @(& winget show @ArgsList --accept-source-agreements --disable-interactivity 2>&1)
        }
        $metadata = [ordered]@{
            Name = ''
            Id = ''
            Version = ''
            Publisher = ''
            InstallerType = ''
            InstallerUrl = ''
            InstallerSha256 = ''
        }

        foreach ($line in $rawLines) {
            $trimmed = [regex]::Replace(($line.ToString()).Trim(), '\x1B\[[0-9;?]*[A-Za-z]', '')
            if (-not $trimmed) { continue }

            if (-not $metadata.Name -and $trimmed -match '^Found\s+(.+?)\s+\[([^\]]+)\]') {
                $metadata.Name = $matches[1].Trim()
                $metadata.Id = $matches[2].Trim()
                continue
            }

            if (-not $metadata.Version -and $trimmed.StartsWith('Version:')) {
                $metadata.Version = $trimmed.Substring('Version:'.Length).Trim()
                continue
            }

            if (-not $metadata.Publisher -and $trimmed.StartsWith('Publisher:')) {
                $metadata.Publisher = $trimmed.Substring('Publisher:'.Length).Trim()
                continue
            }

            if (-not $metadata.InstallerType -and $trimmed.StartsWith('Installer Type:')) {
                $metadata.InstallerType = $trimmed.Substring('Installer Type:'.Length).Trim()
                continue
            }

            if (-not $metadata.InstallerUrl -and $trimmed.StartsWith('Installer Url:')) {
                $metadata.InstallerUrl = $trimmed.Substring('Installer Url:'.Length).Trim()
                continue
            }

            if (-not $metadata.InstallerSha256 -and $trimmed.StartsWith('Installer SHA256:')) {
                $metadata.InstallerSha256 = $trimmed.Substring('Installer SHA256:'.Length).Trim()
            }
        }

        if (-not $metadata.InstallerUrl) { return $null }
        return [pscustomobject]$metadata
    }

